import org.eclipse.rdf4j.query.resultio.TupleQueryResultWriterFactory;
import org.eclipse.rdf4j.query.resultio.TupleQueryResultWriterRegistry;
import org.junit.jupiter.api.Test;

class ExplanationSerializationTest {

	@Test
	void resourceOwningFormatsAreRejectedBeforeCreatingAWriter() {
		TupleQueryResultWriterRegistry registry = TupleQueryResultWriterRegistry.getInstance();
		for (TupleQueryResultFormat format : List.of(TupleQueryResultFormat.ODS, TupleQueryResultFormat.XSLX)) {
			var previous = registry.get(format);
			TupleQueryResultWriterFactory factory = new TupleQueryResultWriterFactory() {
				@Override
				public TupleQueryResultFormat getTupleQueryResultFormat() {
					return format;
				}

				@Override
				public TupleQueryResultWriter getWriter(OutputStream output) {
					throw new AssertionError("must not allocate resource-owning writer before checking support");
				}
			};
			registry.add(factory);
			try {
				assertThatThrownBy(() -> new ExplanationSerializationConsumerFactory()
						.create(format.getDefaultMIMEType(), List.of("value")))
								.isInstanceOf(IllegalArgumentException.class)
								.hasMessageContaining("JSON, XML, binary, CSV, or TSV");
			} finally {
				registry.remove(factory);
				previous.ifPresent(registry::add);
			}
		}
	}

	@Test
	void explanationUsesTheRegisteredWriterAndCountsActualEncodedBytes() {
		List<String> names = List.of("value");
		MapBindingSet row = new MapBindingSet();
		row.addBinding("value", SimpleValueFactory.getInstance().createLiteral("Norwegian: æøå; supplementary: 😀"));
		ByteArrayOutputStream expected = new ByteArrayOutputStream();
		TupleQueryResultWriter writer = QueryResultIO.createTupleWriter(TupleQueryResultFormat.JSON, expected);
		writer.startQueryResult(names);
		writer.handleSolution(row);
		writer.endQueryResult();

		ResultConsumer selected = null;
		for (ExplanationResultConsumerFactory factory : ServiceLoader.load(ExplanationResultConsumerFactory.class)) {
			selected = factory.create(TupleQueryResultFormat.JSON.getDefaultMIMEType(), names);
			if (selected != null) {
				break;
			}
		}
		assertThat(selected).as("query-result IO must register the explanation serialization consumer").isNotNull();
		try (ResultConsumer consumer = selected) {
			consumer.accept(row);
			consumer.finish();
			assertThat(consumer.bytesWritten()).isEqualTo(expected.size());
		}
	}
}
